<?php $cats=function_exists('get_terms')?get_terms(array('taxonomy'=>'product_cat','hide_empty'=>false,'number'=>4)):array();$images=array('https://images.unsplash.com/photo-1523275335684-37898b6baf30?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1548036328-c9fa89d128fa?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1526170375885-4d8ecf77b99d?auto=format&fit=crop&w=800&q=80','https://images.unsplash.com/photo-1494438639946-1ebd1d20bf85?auto=format&fit=crop&w=800&q=80');if(!is_wp_error($cats)&&$cats){foreach($cats as $i=>$cat){ ?><div class="col-6 col-lg-3"><a class="category-tile" href="<?php echo esc_url(get_term_link($cat)); ?>"><img src="<?php echo esc_url($images[$i%4]); ?>" alt="<?php echo esc_attr($cat->name); ?>"><div><h3><?php echo esc_html($cat->name); ?></h3><span>Discover <i class="bi bi-arrow-right"></i></span></div></a></div><?php }}else{for($i=0;$i<4;$i++){ ?><div class="col-6 col-lg-3"><a class="category-tile" href="<?php echo esc_url(function_exists('wc_get_page_permalink')?wc_get_page_permalink('shop'):home_url('/shop')); ?>"><img src="<?php echo esc_url($images[$i]); ?>" alt="Shop category"><div><h3>Category</h3><span>Discover <i class="bi bi-arrow-right"></i></span></div></a></div><?php }} ?></div></div></section>